    {
        "id": "CCP-S323",
        "question": "出于合规性原因，一家公司希望跟踪 AWS 资源配置更改。可以使用哪些 AWS 功能来满足此要求？",
        "question_en": "A company wants to track AWS resource configuration changes for compliance reasons. Which AWS feature can be used to meet this requirement?",
        "options": ["A. AWS 成本和使用情况报告", "B. AWS OrganizationsService Control Policies（SCPs）", "C. AWS Config rules", "D. VPC 流日志"],
        "correct_answers": ["C"],
        "explanation": "正确答案：\n\n「AWS Config 持续监控和记录资源配置更改，并根据合规性规则对其进行评估，生成完整的配置更改历史记录，审核员和合规团队可以使用该历史记录来证明对标准的遵守情况。」\n\n错误选项分析：\n\n「A. AWS 成本和使用情况报告」是错误的：AWS CloudTrail 记录所有 API 调用和帐户活动以用于审计和取证目的，虽然它捕获谁进行了配置更改以及何时更改，但它不会评估这些配置是否符合定义的规则或提供 Config 所做的配置状态历史记录。\n\n「B. AWS OrganizationsService Control Policies（SCPs）」是错误的：Amazon Inspector 是针对 Amazon EC2 instances 和容器镜像的自动化漏洞评估服务，可识别软件漏洞和网络错误配置，并且是安全扫描工具，而不是资源配置跟踪和合规性评估功能。\n\n「D. VPC 流日志」是错误的：AWS Trusted Advisor 提供跨安全、成本、性能和容错类别的自动化建议，并且是一种咨询工具，而不是资源配置更改跟踪和合规性评估服务。",
        "domain": "Security and Compliance",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q1004",
    },
    {
        "id": "CCP-S324",
        "question": "授予最小权限的 AWS IAM 最佳实践是：",
        "question_en": "The AWS IAM best practice for granting least privilege is to:",
        "options": ["A. 将 IAM 策略应用于 IAM 组并限制组的大小", "B. 要求所有 IAM 用户进行多重身份验证 (MFA)", "C. 要求每个具有不同权限的 IAM 用户拥有多个密码", "D. 仅将 IAM 策略应用于需要的 IAM 用户"],
        "correct_answers": ["D"],
        "explanation": "正确答案：\n\n「最小权限原则要求仅授予用户执行其特定工作职能所需的权限，这意味着仅将 IAM 策略应用于实际需要这些权限的用户，而不是在所有用户之间广泛分配权限。」\n\n错误选项分析：\n\n「A. 将 IAM 策略应用于 IAM 组并限制组的大小」是错误的：将 IAM 策略应用于 IAM 组并限制组的大小可解决组管理问题，而不是最小权限问题，因为组的大小与权限是否适当地限制在用户实际需要的范围无关。\n\n「B. 要求所有 IAM 用户进行多重身份验证 (MFA)」是错误的：要求所有 IAM 用户使用 MFA 是一种身份验证安全最佳实践，可防止凭据泄露，但它与将权限范围限定为所需的最低级别无关。\n\n「C. 要求每个具有不同权限的 IAM 用户拥有多个密码」是错误的：要求具有不同权限的 IAM 用户拥有多个密码将身份验证与授权混为一谈，并且拥有多个密码并不能控制或限制允许用户执行的操作。",
        "domain": "Security and Compliance",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q1006",
    },
