    {
        "id": "CCP-S329",
        "question": "以下哪项是 AWS 云中水平扩展的示例？",
        "question_en": "Which of the following is an example of horizontal scaling in the AWS Cloud?",
        "options": ["A. 用更大、更强大的实例替换现有的 Amazon EC2 instances", "B. 增加单个 Amazon EC2 instances 的计算能力，以满足应用程序不断增长的需求", "C. 向 Amazon EC2 instances 添加更多 RAM 容量", "D. 添加更多相同大小的 Amazon EC2 instances 来处理流量的增加"],
        "correct_answers": ["D"],
        "explanation": "正确答案：\n\n「水平扩展意味着添加更多相同大小的实例来分配负载，而垂直扩展意味着增加单个实例的容量。」\n\n错误选项分析：\n\n「A. 用更大、更强大的实例替换现有的 Amazon EC2 instances」是错误的：用更大的实例替换现有实例是垂直缩放，而不是水平缩放。\n\n「B. 增加单个 Amazon EC2 instances 的计算能力，以满足应用程序不断增长的需求」是错误的：增加单个实例的计算能力是垂直扩展，与水平扩展相反。\n\n「C. 向 Amazon EC2 instances 添加更多 RAM 容量」是错误的：向单个实例添加更多 RAM 是垂直扩展的另一种形式，因为它增加了一个实例的功能，而不是添加更多实例。",
        "domain": "Technology and Services",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q002",
    },
    {
        "id": "CCP-S330",
        "question": "一家公司在 AWS 上开发了电子商务 Web 应用程序。他们应该如何确保应用程序具有最高级别的可用性？",
        "question_en": "A company has developed an eCommerce web application on AWS. What should they do to ensure that the application has the highest level of availability?",
        "options": ["A. 跨多个可用区和边缘站点部署应用程序", "B. 跨多个可用区和子网部署应用程序", "C. 跨多个区域和可用区部署应用程序", "D. 跨多个 VPC 和子网部署应用程序"],
        "correct_answers": ["C"],
        "explanation": "正确答案：\n\n「跨多个区域和可用区部署可同时防止可用区级故障和区域级故障，从而提供最高级别的可用性。」\n\n错误选项分析：\n\n「A. 跨多个可用区和边缘站点部署应用程序」是错误的：跨多个可用区和边缘位置部署可增加通过 CloudFront 的内容交付范围，但不能保护应用程序基础设施免受区域故障的影响。\n\n「B. 跨多个可用区和子网部署应用程序」是错误的：跨多个可用区和子网部署可以提高针对区域内孤立故障的恢复能力，但区域中断仍会影响整个部署。\n\n「D. 跨多个 VPC 和子网部署应用程序」是错误的：跨多个 VPC 和子网部署会在一个区域内创建网络分段，但不会针对可用区或区域故障提供地理冗余。",
        "domain": "Technology and Services",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q007",
    },
