    {
        "id": "CCP-S670",
        "question": "在执行支持客户工作负载物理隔离的成本分析时，哪种计算托管模型应计入总拥有成本 (TCO)？",
        "question_en": "When performing a cost analysis that supports physical isolation of a customer workload, which compute hosting model should be accounted for in the Total Cost of Ownership (TCO)?",
        "options": ["A. 专属主机", "B. 预留实例", "C. 按需型实例", "D. 无需预付预留实例"],
        "correct_answers": ["A"],
        "explanation": "正确答案：\n\n「EC2 专属主机在完全专用于一个客户的服务器上提供工作负载的物理隔离，这是某些合规性要求或许可模型所必需的。这种托管模式的成本较高，必须计入 TCO 计算中。」\n\n错误选项分析：\n\n「B. 预留实例」是错误的：预留实例是一项定价承诺，可在 1 或 3 年期限内降低 EC2 成本，虽然它们降低了持续成本，但它们在标准共享基础设施上运行，并且不提供合规性工作负载的 TCO 分析必须考虑的物理隔离。\n\n「C. 按需型实例」是错误的：按需型实例对共享基础设施按小时计费，没有长期承诺，虽然它们对于可变工作负载很有用，但它们不提供物理隔离，并且单位成本较高，无法反映以合规性为中心的 TCO 计算。\n\n「D. 无需预付预留实例」是错误的：无预付费用预留实例通过长期承诺提供比按需的折扣，无需任何初始付款，但与标准预留实例一样，它们在共享基础设施上运行，并且不考虑合规性要求所需的物理隔离成本。",
        "domain": "Billing, Pricing, and Support",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q133",
    },
