    {
        "id": "CCP-S719",
        "question": "您正在使用多个按需 Amazon EC2 instances 来运行您的开发环境。当这些实例不使用时，减少费用的最佳方法是什么？",
        "question_en": "You are using several on-demand EC2 Instances to run your development environment. What is the best way to reduce your charges when these instances are not in use?",
        "options": ["A. 删除附加到实例的所有 EBS 卷", "B. 您无法最小化 On-Demand 实例的费用", "C. 终止实例", "D. 停止实例"],
        "correct_answers": ["D"],
        "explanation": "正确答案：\n\n「停止按需 Amazon EC2 instances 会停止计算费用，同时保留实例及其 EBS 卷，因此您可以稍后重新启动而不会丢失配置或数据。」\n\n错误选项分析：\n\n「A. 删除附加到实例的所有 EBS 卷」是错误的：删除附加到实例的所有 EBS 卷将破坏这些卷上存储的所有数据，这是一种不可逆转的操作，它会消除您的开发环境，而不是简单地减少不使用时的费用。\n\n「B. 您无法最小化 On-Demand 实例的费用」是错误的：可以停止 On-Demand 实例以降低费用，因此费用无法最小化的说法是不正确的。\n\n「C. 终止实例」是错误的：对于间歇性使用的开发环境，建议使用停止实例的方法。终止实例会永久销毁它们以及任何实例存储数据，虽然它确实停止了所有费用，但这是一个不可逆转的操作，需要从头开始重建开发环境。",
        "domain": "Billing, Pricing, and Support",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q413",
    },
