    {
        "id": "CCP-S729",
        "question": "哪些 AWS 服务允许您购买在 AWS 资源上运行的第三方软件解决方案和服务？",
        "question_en": "What AWS service allows you to buy third-party software solutions and services that run on AWS resources?",
        "options": ["A. AWS Application Discovery Service", "B. AWS Cost Explorer", "C. AWS Marketplace", "D. AWS Resource Groups"],
        "correct_answers": ["C"],
        "explanation": "正确答案：\n\n「AWS Marketplace 是一个数字目录，客户可以在其中查找、购买和部署在 AWS 上运行的第三方软件解决方案，包括 AMI、SaaS 应用程序和数据产品。」\n\n错误选项分析：\n\n「A. AWS Application Discovery Service」是错误的：AWS Application Discovery Service 收集有关本地服务器和工作负载的信息以帮助规划云迁移，并且是一种迁移规划工具，无法购买或部署第三方软件。\n\n「B. AWS Cost Explorer」是错误的：AWS Cost Explorer 提供随时间变化的 AWS 支出和使用模式的可视化和分析，它是一种成本管理工具，而不是软件采购平台。\n\n「D. AWS Resource Groups」是错误的：AWS Resource Groups 根据标签或 CloudFormation 堆栈将 AWS Resource Groups 织成逻辑组，以便于管理，并且不参与发现或购买第三方软件解决方案。",
        "domain": "Billing, Pricing, and Support",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q484",
    },
