    {
        "id": "CCP-S765",
        "question": "公司如何隔离 AWS 上的生产和非生产工作负载的成本？",
        "question_en": "How can a company isolate the costs of production and non-production workloads on AWS?",
        "options": ["A. 为生产和非生产工作负载创建身份和访问管理 (IAM) 角色", "B. 生产费用和非生产费用使用不同的账户", "C. 将 Amazon EC2 用于非生产工作负载，将其他服务用于生产工作负载", "D. 使用 Amazon CloudWatch 监控服务的使用情况"],
        "correct_answers": ["B"],
        "explanation": "正确答案：\n\n「对生产和非生产工作负载使用单独的 AWS 账户可以隔离账户级别的成本，从而使计费能够自然地反映每个环境的消耗情况，并可以轻松地独立归因和审查成本。」\n\n错误选项分析：\n\n「A. 为生产和非生产工作负载创建身份和访问管理 (IAM) 角色」是错误的：为生产和非生产工作负载创建 IAM 角色可以控制谁可以访问每个环境的资源，但不会隔离或单独跟踪每个环境产生的成本，因为 IAM 角色是访问控制结构而不是计费边界。\n\n「C. 将 Amazon EC2 用于非生产工作负载，将其他服务用于生产工作负载」是错误的：将 Amazon EC2 用于生产工作负载的非生产服务和其他服务，会按服务类型而不是环境边界对基础设施进行分段，这不会提供干净的成本隔离，并使成本跟踪变得更加复杂而不是简单。\n\n「D. 使用 Amazon CloudWatch 监控服务的使用情况」是错误的：使用 Amazon CloudWatch 监控服务使用情况可以提供对资源消耗的操作可见性，并可以触发与成本相关的警报，但监控使用情况与隔离环境之间的成本不同； CloudWatch 不会在生产和非生产工作负载之间创建计费边界。",
        "domain": "Billing, Pricing, and Support",
        "is_multi": False,
        "source": "cloudcertprep",
        "source_id": "q747",
    },
